#!/usr/bin/env node
/**
 * A change to the projection must come with a version bump.
 *
 * `apps/web/src/data/validation.json` is regenerated by CI, not by hand, so the
 * commit that produced a number is not something a reader can see. Without a
 * version, two runs a month apart are indistinguishable from two runs of the
 * same model on different corpora, and the history in
 * `apps/web/src/data/model-history.json` becomes a list of numbers that cannot
 * be compared with each other.
 *
 * The rule: if any file under `MODEL_PATHS` differs from the base branch,
 * `MODEL_VERSION` in `python/fpl_andres/model_version.py` must differ too.
 * Whether the change is minor or major is a judgement about whether the numbers
 * merely moved or now mean something else, and that is not a judgement a script
 * can make. It only insists that the judgement was made.
 *
 * Same shape as the contracts gate, deliberately: same base-ref resolution,
 * same skip when there is no base branch to compare against.
 */

import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";

/** Anything that can move a projected point. */
const MODEL_PATHS = [
  "python/fpl_andres/models/",
  "python/fpl_andres/backtesting/",
  "python/fpl_andres/rules.py",
];

const VERSION_PATH = "python/fpl_andres/model_version.py";

function git(...args) {
  return execFileSync("git", args, { encoding: "utf8" }).trim();
}

function tryGit(...args) {
  try {
    return git(...args);
  } catch {
    return null;
  }
}

function baseRef() {
  const explicit = process.env.GITHUB_BASE_REF;
  if (explicit) {
    const remote = `origin/${explicit}`;
    if (tryGit("rev-parse", "--verify", remote) !== null) return remote;
  }
  for (const candidate of ["origin/main", "main"]) {
    if (tryGit("rev-parse", "--verify", candidate) !== null) return candidate;
  }
  return null;
}

function versionIn(source) {
  const match = /^MODEL_VERSION\s*=\s*"([^"]+)"/m.exec(source);
  return match ? match[1] : null;
}

const base = baseRef();
if (base === null) {
  console.log(
    "model version gate: no base branch to compare against, skipping.",
  );
  process.exit(0);
}

const mergeBase = tryGit("merge-base", base, "HEAD") ?? base;
// On a push straight to main the base ref IS the commit being checked, so the
// merge base is HEAD and the diff is always empty -- the gate passed on every
// push without looking at anything. The owner works directly on main, so that
// was most of its job. Compare against the preceding commit instead.
const against =
  tryGit("rev-parse", mergeBase) === tryGit("rev-parse", "HEAD")
    ? (tryGit("rev-parse", "--verify", "HEAD^") ?? mergeBase)
    : mergeBase;
const changed = (
  tryGit("diff", "--name-only", against, "--", ...MODEL_PATHS) ?? ""
)
  .split("\n")
  .map((line) => line.trim())
  .filter(Boolean);

if (changed.length === 0) {
  console.log("model version gate: the projection did not change.");
  process.exit(0);
}

const versionNow = versionIn(readFileSync(VERSION_PATH, "utf8"));
if (versionNow === null) {
  console.error(
    `model version gate: no MODEL_VERSION found in ${VERSION_PATH}.`,
  );
  process.exit(1);
}

const before = tryGit("show", `${against}:${VERSION_PATH}`);
const versionBefore = before === null ? null : versionIn(before);

if (versionBefore !== null && versionBefore === versionNow) {
  console.error(
    [
      `The projection changed but MODEL_VERSION is still ${versionNow}.`,
      "",
      ...changed.map((file) => `  ${file}`),
      "",
      `Bump MODEL_VERSION in ${VERSION_PATH}. Minor if the numbers merely`,
      "moved, major if they now mean something else. Every row in",
      "apps/web/src/data/model-history.json is keyed on it, so a version that",
      "does not move makes two different models look like one.",
    ].join("\n"),
  );
  process.exit(1);
}

console.log(
  `model version gate: projection changed and version moved ${String(versionBefore)} -> ${versionNow}.`,
);
